import * as THREE from 'three/webgpu';
import { MeshBasicNodeMaterial, texture } from 'three/tsl';

export default function createNode(config, ctx) {
  // Load the texture via cached loader
  const baseTexture = ctx.textureLoader.load('/prism-mock/home/nodes/orb-decor.png');
  baseTexture.colorSpace = THREE.SRGBColorSpace;
  baseTexture.magFilter = THREE.LinearFilter;
  baseTexture.minFilter = THREE.LinearFilter;

  // Create plane geometry with aspect ratio 512:320 = 1.6:1
  const geometry = new THREE.PlaneGeometry(1.6, 1, 1, 1);

  // Create material using TSL nodes
  const textureNode = texture(baseTexture);
  const material = new MeshBasicNodeMaterial({
    colorNode: textureNode,
    side: THREE.DoubleSide,
    transparent: true,
  });

  // Create mesh
  const mesh = new THREE.Mesh(geometry, material);

  // Apply scene placement from specification
  mesh.position.set(-3.2, -0.3, 0);
  mesh.rotation.set(0, 0, 0);
  mesh.scale.set(1, 1, 1);

  // Initialize event handlers
  mesh.userData.handlers = {};

  // Resource cleanup
  mesh.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    baseTexture.dispose();
  };

  return mesh;
}
